:root { color-scheme: dark; --g0: 2 6 8; --t1: 7 21 26; --t2: 24 70 55; --t3: 18 34 37; --t4: 44 55 71; --g1: 72 178 152; --g2: 143 211 192; --g3: 156 222 201; --g4: 104 196 168; --ink: #e5f3f2; --ink-2: rgb(229 243 242 / .64); --ink-3: rgb(229 243 242 / .44); --ink-4: rgb(229 243 242 / .22); --stroke: rgb(229 243 242 / .12); --hair: rgb(255 255 255 / .055); --panel: rgb(255 255 255 / .026); --gold: #e4d87a; --danger: #eac7c6; --on-bright: #06201a; --mint: rgb(var(--g2)); --ground: rgb(var(--g0)); --r-control: 18px; --r-card: 22px; --r-surface: 28px; --ease-out: cubic-bezier(.23, 1, .32, 1); --ease-io: cubic-bezier(.77, 0, .175, 1); --ease-soft: cubic-bezier(.16, 1, .3, 1); --press: 140ms; --font: -apple-system, BlinkMacSystemFont, system-ui, Roboto, "Segoe UI", sans-serif; --serif: ui-serif, "New York", Georgia, "Times New Roman", serif; --gutter: 16px; --dock-h: 96px; --kb: 0px; background: var(--ground); color: var(--ink); font: 500 15px/1.45 var(--font); letter-spacing: 0.1px; text-size-adjust: 100%; transition: background-color 400ms; }
* { box-sizing: border-box; }
html, body { margin: 0px; min-height: 100%; background: var(--ground); }
body { -webkit-font-smoothing: antialiased; overscroll-behavior-y: none; }
[hidden] { display: none !important; }
h1, h2, h3, p { margin: 0px; }
b { font-weight: 600; }
small { font-size: 12.5px; color: var(--ink-2); }
button, input, select, textarea { font: inherit; color: inherit; letter-spacing: inherit; }
button { margin: 0px; padding: 0px; border: 0px; background: none; cursor: pointer; touch-action: manipulation; -webkit-tap-highlight-color: transparent; user-select: none; }
:focus { outline: none; }
.grow { flex: 1 1 0%; min-width: 0px; }
.ic { display: block; flex: 0 0 auto; }
@property --a-mid { syntax: "<number>"; inherits: false; initial-value: .3; }
@property --a-edge { syntax: "<number>"; inherits: false; initial-value: .3; }
.s { --a: .3; --a-mid: var(--a); --a-edge: var(--a); --c1: var(--t1); --c2: var(--t2); --c3: var(--t3); --c4: var(--t4); background-image: radial-gradient(ellipse at 12% 115%, rgb(var(--c2) / var(--a-mid)), transparent 62%),
    radial-gradient(ellipse at 88% -25%, rgb(var(--c4) / var(--a-mid)), transparent 64%),
    radial-gradient(ellipse at 48% 48%, rgb(var(--c3) / var(--a-edge)), rgb(var(--c1) / var(--a-edge)) 82%); box-shadow: inset 0 0 0 1.2px var(--stroke); transition: --a-mid 110ms var(--ease-out),
    --a-edge 240ms var(--ease-soft) 40ms,
    transform var(--press) var(--ease-out),
    color 110ms var(--ease-out),
    opacity 160ms var(--ease-out),
    box-shadow 160ms var(--ease-out); }
.s.ash { --c1: 22 24 26; --c2: 40 43 45; --c3: 43 45 47; --c4: 40 44 48; }
.s.danger { --c1: 92 16 16; --c2: 118 26 26; --c3: 120 34 34; --c4: 75 18 18; color: var(--danger); }
.s.go, .s.caution { --a: .86; color: var(--on-bright); font-weight: 650; box-shadow: inset 0 1px 0 rgb(255 255 255 / .3), 0 8px 22px -12px rgb(var(--c2) / .8); }
.s.go { --c1: var(--g1); --c2: var(--g2); --c3: var(--g3); --c4: var(--g4); }
.s.caution { --c1: 201 178 78; --c2: 228 216 122; --c3: 236 225 142; --c4: 212 192 96; }
@media (hover: hover) and (pointer: fine) {button.s:hover:not([aria-disabled="true"]) { --a: .7; }
button.s.go:hover:not([aria-disabled="true"]), button.s.caution:hover:not([aria-disabled="true"]) { --a: 1; }}
[aria-disabled="true"] { opacity: 0.38; }
.btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 48px; padding: 0px 16px; border-radius: var(--r-control); font-size: 15px; font-weight: 550; white-space: nowrap; }
.btn.small { min-height: 38px; padding: 0px 13px; border-radius: 14px; font-size: 13.5px; }
.btn.wide { width: 100%; }
@supports (corner-shape: superellipse(1.6)) {.btn, .card, .row, .catch, .lyric, .monitor, .slide, .seg, .up-next, .search-field, .group-card, .sheet, .banner, .field, .code { corner-shape: superellipse(1.6); }}
.eyebrow { font-size: 11px; font-weight: 600; letter-spacing: 0.14em; text-transform: uppercase; color: var(--ink-3); }
.top { position: sticky; top: 0px; z-index: 10; display: flex; align-items: center; gap: 8px; padding: calc(10px + env(safe-area-inset-top)) var(--gutter) 10px; background: rgb(var(--g0) / .76); backdrop-filter: blur(18px) saturate(120%); }
.brand { display: flex; align-items: center; gap: 10px; margin-right: auto; min-width: 0px; }
.mark { width: 28px; height: 28px; color: var(--ink); flex: 0 0 auto; }
.brand-words { display: flex; flex-direction: column; min-width: 0px; line-height: 1.1; }
.brand-name { font-size: 17px; font-weight: 650; letter-spacing: -0.35px; }
.conn { display: flex; align-items: center; gap: 6px; margin-top: 3px; font-size: 12px; font-weight: 500; color: var(--ink-3); }
.conn.ok { color: var(--mint); }
.pill { min-height: 38px; padding: 0px 14px; border-radius: 999px; font-size: 13.5px; }
.pill .dot { width: 7px; height: 7px; border-radius: 50%; background: var(--ink-4); flex: 0 0 auto; }
.pill[data-asr="listening"] .dot { background: var(--mint); box-shadow: 0 0 0 3px rgb(var(--g2) / .18); }
.round { width: 40px; height: 40px; min-height: 40px; padding: 0px; border-radius: 50%; }
.banner { margin: 10px var(--gutter) 0; padding: 14px 16px; border-radius: var(--r-card); }
.banner.error { background: rgba(234, 199, 198, 0.07); box-shadow: rgba(234, 199, 198, 0.24) 0px 0px 0px 1.2px inset; color: var(--danger); font-size: 14px; }
.banner.prompt { background: rgba(228, 216, 122, 0.06); box-shadow: rgba(228, 216, 122, 0.3) 0px 0px 0px 1.2px inset; }
.banner.prompt h2 { font-size: 16px; font-weight: 650; letter-spacing: -0.2px; }
.banner.prompt p { margin-top: 4px; font-size: 13px; color: var(--ink-2); }
.banner .actions { display: flex; gap: 8px; margin-top: 12px; }
.banner .actions .btn { flex: 1 1 0%; }
.monitor { margin: 6px var(--gutter) 0; padding: 6px; border-radius: var(--r-surface); background: var(--panel); box-shadow: inset 0 0 0 1.2px var(--hair); }
.slide { position: relative; overflow: hidden; display: flex; flex-direction: column; min-height: 138px; padding: 16px 16px 14px; border-radius: calc(var(--r-surface) - 6px); background: radial-gradient(120% 100% at 50% 0%, rgb(var(--t2) / .16), transparent 72%), #000; box-shadow: rgba(255, 255, 255, 0.043) 0px 0px 0px 1px inset; }
.slide-img { position: absolute; inset: 0px; width: 100%; height: 100%; object-fit: cover; opacity: 0.92; }
.slide-foot { display: flex; align-items: center; gap: 8px; min-height: 34px; padding: 6px 8px 2px 10px; }
.on-air { display: flex; align-items: center; gap: 7px; margin-right: auto; }
.chip { font-size: 11.5px; font-weight: 650; letter-spacing: 0.02em; padding: 3px 9px; border-radius: 999px; color: var(--gold); background: rgba(228, 216, 122, 0.12); }
.slide-body { position: relative; flex: 1 1 0%; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 2px 2px 0px; transition: opacity 200ms var(--ease-out); }
.monitor:not([data-screen="live"]) .slide-body { opacity: 0.24; }
.slide-text { font-family: var(--serif); font-weight: 500; color: rgb(255, 255, 255); white-space: pre-line; text-shadow: rgba(0, 0, 0, 0.5) 0px 1px 3px; letter-spacing: 0px; display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 4; overflow: hidden; }
.fit-2 { font-size: 18px; line-height: 1.36; }
.slide-caption { margin-top: 9px; font-size: 12px; font-weight: 600; letter-spacing: 0.03em; color: rgba(255, 255, 255, 0.62); }
.slide-credit { margin-top: 4px; font-size: 10.5px; line-height: 1.35; color: rgba(255, 255, 255, 0.45); }
.seg { position: relative; display: grid; grid-template-columns: repeat(var(--n, 3), 1fr); margin: 16px var(--gutter) 4px; padding: 4px; border-radius: 17px; background: rgba(255, 255, 255, 0.024); box-shadow: inset 0 0 0 1.2px var(--hair); }
.seg-thumb { --a: .62; position: absolute; top: 4px; bottom: 4px; left: 4px; width: calc((100% - 8px) / var(--n, 3)); border-radius: 13px; transform: translateX(calc(var(--i, 0) * 100%)); transition: transform 260ms var(--ease-out), --a-mid 110ms var(--ease-out), --a-edge 240ms var(--ease-soft); }
.seg button { position: relative; z-index: 1; min-height: 42px; display: flex; align-items: center; justify-content: center; gap: 7px; font-size: 14.5px; color: var(--ink-3); transition: color 160ms; }
.seg button[aria-selected="true"], .seg button[aria-checked="true"] { color: var(--ink); }
.badge { min-width: 19px; height: 19px; padding: 0px 5px; border-radius: 10px; display: inline-flex; align-items: center; justify-content: center; background: var(--mint); color: var(--on-bright); font-size: 11.5px; font-weight: 700; letter-spacing: 0px; }
.panel { padding: 0 var(--gutter) calc(var(--dock-h) + var(--kb) + 32px); }
.section-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin: 16px 4px 9px; min-height: 22px; }
.section-head small { font-size: 12.5px; }
.list { display: grid; gap: 8px; }
.row { display: flex; align-items: center; gap: 12px; width: 100%; text-align: left; padding: 13px 14px 13px 16px; border-radius: var(--r-card); background: var(--panel); box-shadow: inset 0 0 0 1.2px var(--hair); transition: transform var(--press) var(--ease-out), background-color 160ms var(--ease-out); }
.row .ic { color: var(--ink-3); }
.row-text { flex: 1 1 0%; min-width: 0px; display: flex; flex-direction: column; gap: 2px; }
.row-title { font-size: 15.5px; font-weight: 600; letter-spacing: -0.15px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.row-sub { font-size: 13px; color: var(--ink-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.catch { position: relative; display: flex; align-items: stretch; border-radius: var(--r-card); background: var(--panel); box-shadow: inset 0 0 0 1.2px var(--hair); transition: box-shadow 200ms var(--ease-out), opacity 260ms var(--ease-out), transform 260ms var(--ease-out); }
@starting-style {.catch { opacity: 0; transform: translateY(8px); }}
.catch.is-live { box-shadow: rgba(228, 216, 122, 0.45) 0px 0px 0px 1.2px inset; }
.catch-main { flex: 1 1 0%; min-width: 0px; text-align: left; padding: 14px 4px 14px 16px; border-radius: var(--r-card) 0 0 var(--r-card); transition: transform var(--press) var(--ease-out); }
.catch-top { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.catch-ref { font-size: 16.5px; font-weight: 650; letter-spacing: -0.25px; }
.tag { font-size: 11px; font-weight: 650; letter-spacing: 0.02em; padding: 2px 8px; border-radius: 999px; background: rgba(255, 255, 255, 0.06); color: var(--ink-2); }
.tag.is-live { color: var(--gold); background: rgba(228, 216, 122, 0.12); }
.catch-text { margin-top: 5px; font-family: var(--serif); font-size: 14.5px; line-height: 1.45; color: var(--ink-2); display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden; }
.catch-hint { margin-top: 7px; font-size: 12.5px; color: var(--gold); }
.catch-x { flex: 0 0 50px; display: grid; place-items: center; color: var(--ink-3); border-radius: 0 var(--r-card) var(--r-card) 0; transition: color 120ms ease, transform var(--press) var(--ease-out); }
.field { width: 100%; min-height: 48px; padding: 0px 14px; border: 0px; border-radius: 16px; background: rgba(255, 255, 255, 0.035); box-shadow: inset 0 0 0 1.2px var(--hair); color: var(--ink); font-size: 16px; }
.switch-row { display: flex; align-items: center; gap: 12px; padding: 12px 14px 12px 16px; border-radius: var(--r-card); background: var(--panel); box-shadow: inset 0 0 0 1.2px var(--hair); margin-bottom: 8px; }
.switch-row b { display: block; font-size: 15px; }
.switch { position: relative; flex: 0 0 auto; width: 51px; height: 31px; border-radius: 16px; background: rgba(255, 255, 255, 0.14); transition: background-color 220ms var(--ease-out); }
.dock { position: fixed; left: 0px; right: 0px; bottom: var(--kb); z-index: 20; padding: 10px var(--gutter) calc(10px + env(safe-area-inset-bottom)); background: rgb(var(--g0) / .82); backdrop-filter: blur(22px) saturate(120%); box-shadow: rgba(255, 255, 255, 0.05) 0px 1px 0px inset; }
.dock-inner { position: relative; max-width: 560px; margin: 0px auto; }
.up-next { display: flex; align-items: center; gap: 12px; margin-bottom: 8px; padding: 9px 14px 10px; border-radius: 18px; background: rgb(var(--g2) / .07); box-shadow: inset 0 0 0 1.2px rgb(var(--g2) / .3); }
.up-next .eyebrow { color: var(--mint); font-size: 10.5px; }
.ready-label { font-size: 15px; font-weight: 650; letter-spacing: -0.15px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ready-text { font-size: 13px; color: var(--ink-2); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ready-img { width: 54px; height: 31px; border-radius: 8px; object-fit: cover; flex: 0 0 auto; box-shadow: inset 0 0 0 1px var(--hair); }
.transport { display: flex; gap: 6px; }
.transport .btn { min-height: 54px; }
.transport .step { flex: 0 0 50px; padding: 0px; }
#searchOpen { flex: 0 0 46px; padding: 0px; }
#goLive { flex: 1 1 0%; min-width: 0px; font-size: 16px; }
#clearScreen { flex: 0 0 auto; min-width: 78px; padding: 0px 12px; }
.search { display: none; align-items: center; gap: 8px; }
.search-field { position: relative; flex: 1 1 0%; min-width: 0px; display: flex; align-items: center; gap: 4px; min-height: 52px; padding: 0px 5px 0px 14px; border-radius: var(--r-control); }
.search-field > .ic { color: var(--ink-3); margin-right: 4px; }
.reference-wrap { position: relative; flex: 1 1 0%; min-width: 0px; }
#reference { position: relative; z-index: 1; width: 100%; padding: 13px 0px; border: 0px; background: none; color: var(--ink); caret-color: var(--mint); font-size: 16px; font-weight: 500; }
#referenceTokens { position: absolute; inset: 0px; display: flex; align-items: center; pointer-events: none; white-space: pre; overflow: hidden; font-size: 16px; font-weight: 500; }
#version { appearance: none; flex: 0 0 auto; max-width: 76px; padding: 8px; border: 0px; border-radius: 10px; background: rgba(255, 255, 255, 0.05); color: var(--ink-2); font-size: 12.5px; font-weight: 650; letter-spacing: 0.03em; text-align: center; }
#version option { background: rgb(20, 26, 27); color: var(--ink); }
@supports (-webkit-touch-callout: none) {#version { font-size: 16px; max-width: 84px; }}
#loadVerse { width: 42px; min-height: 42px; padding: 0px; border-radius: 14px; flex: 0 0 auto; }
#searchClose { flex: 0 0 auto; min-height: 48px; padding: 0px 4px; color: var(--mint); font-size: 15px; font-weight: 550; }
#suggestions { position: absolute; left: 0px; right: 0px; bottom: calc(100% + 10px); max-height: min(46vh, 360px); overflow: auto; padding: 6px; border-radius: var(--r-card); background: rgba(17, 19, 20, 0.97); box-shadow: inset 0 0 0 1.2px var(--stroke), 0 -18px 44px rgb(0 0 0 / .5); overscroll-behavior: contain; transform-origin: 50% 100%; }
.toast { position: fixed; left: 50%; bottom: calc(var(--kb) + var(--dock-h) + 12px); z-index: 30; max-width: calc(100% - 2 * var(--gutter)); display: flex; align-items: center; gap: 8px; padding: 10px 15px; border-radius: 999px; pointer-events: none; background: rgba(21, 23, 24, 0.96); box-shadow: inset 0 0 0 1.2px var(--stroke), 0 12px 32px rgb(0 0 0 / .45); font-size: 14px; font-weight: 550; opacity: 0; transform: translate(-50%, 8px) scale(0.98); transition: opacity 160ms var(--ease-out), transform 220ms var(--ease-out); }
.toast.show { opacity: 1; transform: translate(-50%, 0px) scale(1); transition-duration: 200ms, 260ms; }
.toast span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.sheet-root { position: fixed; inset: 0px; z-index: 40; }
.scrim { position: absolute; inset: 0px; background: rgba(0, 0, 0, 0.55); }
.sheet { position: absolute; left: 0px; right: 0px; bottom: 0px; display: flex; flex-direction: column; max-height: calc(100% - 36px - env(safe-area-inset-top)); max-width: 640px; margin: 0px auto; border-radius: 28px 28px 0px 0px; background: color-mix(in srgb, rgb(var(--g0)) 93%, white); box-shadow: rgba(255, 255, 255, 0.06) 0px 1px 0px inset, rgba(0, 0, 0, 0.5) 0px -24px 60px; will-change: transform; }
.sheet-head { flex: 0 0 auto; padding: 8px var(--gutter) 8px; touch-action: none; cursor: grab; }
.grabber { width: 38px; height: 5px; margin: 0px auto 10px; border-radius: 3px; background: rgba(255, 255, 255, 0.2); }
.sheet-title { display: flex; align-items: center; justify-content: space-between; }
.sheet-title h2 { font-size: 21px; font-weight: 700; letter-spacing: -0.45px; }
.sheet-body { overflow: auto; overscroll-behavior: contain; padding: 4px var(--gutter) calc(24px + env(safe-area-inset-bottom)); }
.group { margin-top: 20px; }
.group:first-child { margin-top: 6px; }
.group > .eyebrow { display: block; margin: 0px 4px 8px; }
.group .seg { margin: 0px 0px 8px; --n: 4; }
.group-card { border-radius: var(--r-card); background: rgba(255, 255, 255, 0.03); box-shadow: inset 0 0 0 1.2px var(--hair); overflow: hidden; }
.group-row { display: flex; align-items: center; gap: 12px; min-height: 56px; padding: 9px 12px 9px 16px; }
.group-row + .group-row { box-shadow: inset 0 1px 0 var(--hair); }
.group-row b { display: block; font-size: 15px; }
.group-row small { display: block; margin-top: 1px; font-size: 12.5px; }
.group-row select { appearance: none; padding: 8px 12px; border: 0px; border-radius: 12px; background: rgba(255, 255, 255, 0.06); color: var(--ink); font-size: 16px; }
.inline-form { display: flex; gap: 8px; margin-top: 8px; }
.inline-form .field { flex: 1 1 0%; min-width: 0px; }
.inline-form .minutes { flex: 0 0 74px; text-align: center; }
.link { margin-top: 6px; min-height: 40px; padding: 0px 4px; color: var(--ink-2); font-size: 13.5px; }
.pair { min-height: 100dvh; max-width: 420px; margin: 0px auto; display: flex; flex-direction: column; justify-content: center; padding: calc(28px + env(safe-area-inset-top)) 24px calc(28px + env(safe-area-inset-bottom)); }
.pair .mark { width: 50px; height: 50px; margin-bottom: 26px; }
.pair h1 { margin: 10px 0px 12px; font-size: 31px; line-height: 1.08; font-weight: 750; letter-spacing: -0.9px; }
.pair > p { font-size: 15px; line-height: 1.5; color: var(--ink-2); }
.pair label { display: block; margin: 22px 4px 8px; font-size: 13px; color: var(--ink-2); }
.code { width: 100%; min-height: 64px; border: 0px; border-radius: 20px; text-align: center; background: rgba(255, 255, 255, 0.035); box-shadow: inset 0 0 0 1.2px var(--stroke); color: var(--ink); font-size: 30px; font-weight: 650; letter-spacing: 0.38em; text-indent: 0.38em; font-variant-numeric: tabular-nums; }
.pair .btn.wide { margin-top: 22px; min-height: 54px; font-size: 16px; }
.pair-note { min-height: 22px; margin-top: 14px; font-size: 14px; color: var(--ink-2); display: flex; align-items: center; gap: 9px; }
@keyframes spin {100% { transform: rotate(360deg); }}
.fine { margin-top: 24px; font-size: 12.5px; line-height: 1.55; color: var(--ink-3); }
@media (max-width: 360px) {:root { --gutter: 12px; }
.transport .step { flex-basis: 44px; }
#clearScreen { min-width: 68px; }}
@media (min-width: 600px) {.monitor, .seg, .banner { max-width: 560px; margin-left: auto; margin-right: auto; }
.panel { max-width: 592px; margin: 0px auto; }}
@media (prefers-reduced-motion: reduce) {*, ::before, ::after { transition-duration: 1ms !important; transition-delay: 0s !important; animation-duration: 1ms !important; }}
@media (prefers-reduced-transparency: reduce) {.top, .dock { background: var(--ground); backdrop-filter: none; }}
@media (prefers-contrast: more) {:root { --hair: rgb(255 255 255 / .2); --stroke: rgb(229 243 242 / .35); --ink-3: rgb(229 243 242 / .7); }}
